async function passwordDigest(value){
 const data=new TextEncoder().encode(String(value));
 if(window.crypto&&crypto.subtle){const digest=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')}
 // Compatibility fallback for local previews only; use HTTPS/server auth for real security.
 let h=2166136261;for(const ch of String(value)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return 'local-'+(h>>>0).toString(16);
}
