// Enemy and boss balancing: each minion class has its own hull and weapon damage.
const ENEMY_STATS = {
  red:    { hp: 80,  damage: 8,  name: 'RED INTERCEPTOR',   sprite: 1, color: '#ff4b64', radius: 18, pattern: 0 },
  green:  { hp: 120, damage: 12, name: 'GREEN STRIKER',     sprite: 2, color: '#52ff9b', radius: 18, pattern: 1 },
  purple: { hp: 160, damage: 16, name: 'PURPLE CASTER',     sprite: 3, color: '#cf62ff', radius: 18, pattern: 2 },
  orange: { hp: 220, damage: 22, name: 'ORANGE HEAVY',      sprite: 4, color: '#ffad43', radius: 21, pattern: 3 },
  cyan:   { hp: 100, damage: 10, name: 'CYAN SCOUT',        sprite: 5, color: '#43eaff', radius: 16, pattern: 0 },
  yellow: { hp: 185, damage: 19, name: 'YELLOW BOMBER',     sprite: 6, color: '#ffe15a', radius: 20, pattern: 1 },
  black:  { hp: 280, damage: 28, name: 'OBSIDIAN DESTROYER',sprite: 7, color: '#d4d9e8', radius: 23, pattern: 3 }
};
const BOSS_STATS = [
  { name: 'SECTOR WARDEN', hp: 500, damage: 15 },
  { name: 'VOID COLOSSUS', hp: 2625, damage: 20 },
  { name: 'CRIMSON DEVOURER', hp: 4750, damage: 25 },
  { name: 'ABYSSAL TITAN', hp: 6875, damage: 30 },
  { name: 'INFINITE SOVEREIGN', hp: 9000, damage: 35 }
];
function spawnEnemy() {
  const isBossRound = game.round % 10 === 0;
  if (isBossRound && !game.boss && game.bossSpawnedRound !== game.round) {
    game.bossSpawnedRound = game.round;
    const bossIndex = (Math.floor(game.round / 10) - 1) % BOSS_STATS.length;
    const stats = BOSS_STATS[bossIndex];
    const cycles = Math.floor((game.round - 10) / 50);
    const bossHealth = stats.hp + Math.max(0, cycles) * 500;
    game.boss = {
      x: W / 2, y: 110, hp: bossHealth, max: bossHealth,
      r: 43, t: 0, phase: 0, phaseNo: 1, fire: 0, attack: 0,
      bossIndex, damage: stats.damage, name: stats.name
    };
    $('bossBarWrap').classList.remove('hidden');
    startMusic('boss');
    $('bossName').textContent = stats.name + ' · PHASE I';
    updateBossHealthBar();
    return;
  }
  // Minion spawn weights: M1 100%, M2 90%, M3 70%, M4 60%, M5 50%, M6-M7 40%.
  // A single spawn attempt can create only ONE minion; weighted selection favors
  // common minions and makes the rarer, stronger minions appear less often.
  const enemySpawnWeights = [
    ['red', 100], ['green', 90], ['purple', 70], ['orange', 60],
    ['cyan', 50], ['yellow', 40], ['black', 40]
  ];
  const totalSpawnWeight = enemySpawnWeights.reduce((sum, item) => sum + item[1], 0);
  let spawnRoll = Math.random() * totalSpawnWeight;
  let type = enemySpawnWeights[0][0];
  for (const [enemyType, weight] of enemySpawnWeights) {
    spawnRoll -= weight;
    if (spawnRoll < 0) { type = enemyType; break; }
  }
  const stats = ENEMY_STATS[type];
  // Enemy HP is a percentage of its original HP based on the current round.
  const round = game.round;
  const hpMultiplier = round <= 2 ? 0.10
    : round <= 5 ? 0.30
    : round <= 8 ? 0.60
    : 1.00;
  // Always scale from immutable base stats, never from a previously scaled HP value.
  const originalHP = stats.hp;
  const enemyHealth = Math.max(1, Math.ceil(originalHP * hpMultiplier));
  game.enemies.push({
    x: rand(35, W - 35), y: -35, hp: enemyHealth, max: enemyHealth,
    damage: stats.damage, r: stats.radius,
    vy: rand(45, 72) + Math.min(35, game.round * 1.4),
    vx: rand(-35, 35), t: 0,
    pattern: Math.max(0, Math.min(6, stats.sprite - 1)), minionIndex: stats.sprite,
    fire: rand(game.round<=2?2.6:game.round<=5?1.7:0.8, game.round<=2?3.8:game.round<=5?2.8:1.8), type
  });
}

// Update both the colored boss bar and the readable health numbers.
function updateBossHealthBar() {
  if (!game.boss) return;

  const healthPercent = Math.max(0, (game.boss.hp / game.boss.max) * 100);
  $('bossBar').style.width = healthPercent + '%';

  const healthText = $('bossHealthText');
  if (healthText) {
    healthText.textContent = Math.ceil(Math.max(0, game.boss.hp))
      + ' / ' + game.boss.max + ' HP';
  }
}

function shootEnemy(e){
 const speed=(game.round<=2?105:game.round<=5?135:165)+Math.min(70,game.round*1.8);
 const player=game.player;
 const validTarget=player&&Number.isFinite(player.x)&&Number.isFinite(player.y)&&Number.isFinite(e.x)&&Number.isFinite(e.y);
 const aimed=validTarget?Math.atan2(player.y-e.y,player.x-e.x):Math.PI/2;
 const push=(ang,v=speed)=>game.enemyBullets.push({team:'enemy',source:'minion',damage:e.damage||12,x:e.x,y:e.y+12,vx:Math.cos(ang)*v,vy:Math.sin(ang)*v,r:e.type==='black'?6:(e.type==='orange'||e.type==='yellow'?5:4),color:(ENEMY_STATS[e.type]||ENEMY_STATS.red).color});

 // Enemy attack progression by round:
 // Rounds 1-2: every minion fires one fixed straight-down bullet.
 if(game.round<=2){
  push(Math.PI/2);
  return;
 }

 // Rounds 3-5: aimed single shots are unlocked, but spread/multi-shot
 // patterns remain disabled until round 6.
 if(game.round<=5){
  if(e.pattern>=4 && validTarget) push(aimed);
  else push(Math.PI/2);
  return;
 }

 // Round 6+: unlock each minion's full attack pattern, including spread.
 switch(e.pattern){
  case 0: push(Math.PI/2); break; // Minion 1: straight down
  case 1: for(let i=-1;i<=1;i++)push(Math.PI/2+i*.25); break; // Minion 2: fixed triple
  case 2: for(let i=-2;i<=2;i++)push(Math.PI/2+i*.16); break; // Minion 3: fixed spread
  case 3: for(let burst=0;burst<3;burst++)for(let i=-1;i<=1;i++)push(Math.PI/2+i*.2,speed*(burst===1?.85:1)); break; // Minion 4: burst volley
  case 4: push(aimed); break; // Minion 5: aimed single shot
  case 5: for(let i=-2;i<=2;i++)push(aimed+i*.18); break; // Minion 6: aimed spread
  case 6: push(aimed); for(let i=-2;i<=2;i++)push(aimed+i*.22,speed*.9); break; // Minion 7: aimed + multi-shot
  default: push(Math.PI/2);
 }
}
function playerShoot(){
 const p=game.player,ship=SHIPS.find(s=>s.id===save.ship)||SHIPS[0];
 const gunLevel=Math.max(1,Math.min(5,Number(save.gun)||1));
 // Triangle firing pattern: level 1 = 1 bullet, level 2 = 3, level 3+ = 5.
 // Mas nasa unahan ang gitnang bala; mas nasa likod ang mga bala sa gilid.
 const formationCount=gunLevel===1?1:(gunLevel===2?3:5);
 // Weapon Spread (save.gun) only changes bullet formation/escort visuals; Weapon Core alone grants upgrade damage.
 const baseDamage=ship.gun+Math.max(0,(Number(save.weaponLevel)||1)-1);
 const type=ship.weapon;
 const spacing=type==='shotgun'?22:16;
 const trianglePositions = formationCount===1
  ? [{x:0,y:0}]
  : formationCount===3
   ? [{x:0,y:0},{x:-spacing,y:spacing*.7},{x:spacing,y:spacing*.7}]
   : [{x:0,y:0},{x:-spacing,y:spacing*.7},{x:spacing,y:spacing*.7},{x:-spacing*1.7,y:spacing*1.4},{x:spacing*1.7,y:spacing*1.4}];
 trianglePositions.forEach((position)=>{
  let bulletType='pulse',r=4,damage=baseDamage,vy=-500,explode=false,pierce=false;
  // Primary-fire shots are non-piercing: they disappear on the first enemy hit. Only skill-created projectiles explicitly opt into piercing.
  if(type==='laser'){bulletType='laser';r=5;vy=-570;damage*=1.12;pierce=false}
  else if(type==='missile'){bulletType='missile';r=6;vy=-330;damage*=1.2;explode=true}
  else if(type==='explosive'){bulletType='explosive';r=7;vy=-410;damage*=1.5;explode=true}
  else if(type==='shotgun'){r=3.8;vy=-490;damage*=.9}
  game.bullets.push({team:'player',source:'primary',x:p.x+position.x,y:p.y-22+position.y,vx:0,vy,r,damage,color:ship.color,type:bulletType,explode,pierce,homing:false});
 });
 // Escort mini-ships fire whenever the player fires: Lv.4 has one escort, Lv.5 has two.
 // Keep their shots aligned with the visible mini-ship positions in draw().
 const escortOffset = W * 0.12;
 const escortBehind = 30;
 const escortPositions = gunLevel >= 5 ? [-escortOffset, escortOffset] : (gunLevel === 4 ? [-escortOffset] : []);
 escortPositions.forEach((offset)=>{
  let escortType='pulse',escortR=4,escortDamage=baseDamage,escortVy=-500,escortExplode=false;
  if(type==='laser'){escortType='laser';escortR=5;escortVy=-570;escortDamage*=1.12}
  else if(type==='missile'){escortType='missile';escortR=6;escortVy=-330;escortDamage*=1.2;escortExplode=true}
  else if(type==='explosive'){escortType='explosive';escortR=7;escortVy=-410;escortDamage*=1.5;escortExplode=true}
  else if(type==='shotgun'){escortR=3.8;escortVy=-490;escortDamage*=.9}
  game.bullets.push({team:'player',source:'wing-cannon',x:p.x+offset,y:p.y+escortBehind,vx:0,vy:escortVy,r:escortR,damage:escortDamage,color:ship.color,type:escortType,explode:escortExplode,pierce:false,homing:false});
 });
 if(save.sound&&Math.random()<.5)beep(type==='laser'?900:type==='missile'?300:660,.04);
}

let musicAudio=null,musicMode=null;
const MUSIC_TRACKS={lobby:'assets/user-assets/music/Menu%20Screen.ogg',game:'assets/user-assets/music/Ingame%20music.ogg',boss:'assets/user-assets/music/Boss%20Theme.ogg',result:'assets/user-assets/music/Game%20Over%20Tune.ogg',intro:'assets/user-assets/music/GameIntro.ogg'};
function startMusic(mode='game'){if(!save.sound)return;const track=MUSIC_TRACKS[mode]||MUSIC_TRACKS.game;if(musicAudio&&musicMode===mode&&!musicAudio.paused)return;stopMusic();try{musicAudio=new Audio(track);musicAudio.loop=mode!=='result';musicAudio.preload='auto';musicAudio.volume=Math.max(0,Math.min(1,save.musicVolume??.22));musicMode=mode;musicAudio.play().catch(()=>{ /* Audio is optional; never block gameplay or deployment. */ });}catch(e){stopMusic()}}
