const shipSpriteCache={};
function shipSprite(path){
 // All game assets are relative to index.html. Keep original PNG ship art.
 const clean=String(path||'').replace(/^\.\//,'').replace(/^assets\//,'');
 if(!shipSpriteCache[clean]){
  const im=new Image();
  im.decoding='async';
  im.src='assets/'+clean;
  shipSpriteCache[clean]=im;
 }
 return shipSpriteCache[clean];
}
