// Each special ability has its own handler. The dispatcher only validates the ID,
// starts the cooldown, and calls the matching function; effects never fall back to shield.

// Boss-balance rule: only projectile collisions may damage bosses. Cap each hit
// so a single projectile cannot erase a boss regardless of skill multipliers.
function damageBossFromProjectile(projectileDamage){
 if(!game.boss||!Number.isFinite(projectileDamage)||projectileDamage<=0)return;
 const perHitCap=Math.max(1,game.boss.max*0.025); // at most 2.5% of current boss max HP per projectile hit
 game.boss.hp=Math.max(0,game.boss.hp-Math.min(projectileDamage,perHitCap));
}

function skillRing(p,radius,damage,color,duration=.8){
 game.effects.push({type:'ring',x:p.x,y:p.y,radius,t:0,duration,color});makeParticles(p.x,p.y,color,34);
 for(const e of game.enemies){if(Math.hypot(e.x-p.x,e.y-p.y)<radius){e.hp-=damage;if(e.hp<=0&&!e.dead){e.dead=true;game.kills++;game.score+=100;award(2);updateMissionProgress('kills',1)}}}
 game.enemyBullets=game.enemyBullets.filter(b=>Math.hypot(b.x-p.x,b.y-p.y)>radius);
 // Area-wave visuals may clear regular enemies, but never damage a boss directly.
}
